import re
with open('doc/Laboratory.md') as f: txt = f.read()
# Get all patient info with birthdate and testdate
abnorm_pats = ['3182521', '128012', '4792459', '444499', '5093771', '2340311', '4923796', '5441886', '4634342']

# Extract birthdates from Patient.md
with open('doc/Patient.md') as f: pat_txt = f.read()
births = {}
for pid in abnorm_pats:
    start = pat_txt.find(pid)
    if start >= 0:
        ctx = pat_txt[start:start+300].lower()
        bd = re.search(r'born\s+(?:on\s+)?(\w+)\s+(\d+)\s*(?:st|nd|rd|th)?,\s*(\d{4})', ctx)
        if bd:
            month, day, year = bd.groups()
            births[pid] = {'month':month, 'day':int(day), 'year':int(year)}
print('Birthdates:', births)

# Extract test dates from Lab.md
with open('doc/Laboratory.md') as f: lab_txt = f.read()
tests = {}
for pid in abnorm_pats:
    start = lab_txt.lower().find('patient ' + pid)
    if start >= 0:
        ctx = lab_txt[start:start+400].lower()
        td = re.search(r'(january|february|march|april|may|june|july|august|september|october|november|december)\s+(\d+)', ctx)
        if td:
            month, day = td.groups()
            # Find year too
            yr = re.search(r'(\d{4})', ctx[td.end():])
            year = int(yr.group(1)) if yr else 0
            tests[pid] = {'month':month, 'day':int(day), 'year':year}
print('Test dates:', tests)

# Calculate ages
for pid in abnorm_pats:
    if pid in births and pid in tests:
        b = births[pid]
        t = tests[pid]
        # Simplified age calculation
        age = t['year'] - b['year']
        if t['month'] < b['month'] or (t['month'] == b['month'] and t['day'] < b['day']):
            age -= 1
        print(f'{pid}: age {age} (born {b["year"]}, test {t["year"]})')
    elif pid in births:
        print(f'{pid}: no test date found')
    elif pid in tests:
        print(f'{pid}: no birthdate found')
    else:
        print(f'{pid}: neither found')

